// ---- runtime helpers (action fns registered in mod.js DNC list) --------
function eraGate(i) {
	var GATES = [new Decimal("1e10"), new Decimal("1e30"), new Decimal("1e300"), new Decimal("1e3000")];
	return GATES[Math.max(0, Math.min(3, i))];
}
function eraIndex() {
	// Era boundaries use gates 1-3 so the era label matches when each era
	// tab actually opens (gate 0 = 1e10 is the bars/sparks threshold).
	var p = player.t.points
	if (p.gte(eraGate(3))) return 3;
	if (p.gte(eraGate(2))) return 2;
	if (p.gte(eraGate(1))) return 1;
	return 0;
}
/** The era's named secondary resource (K4/K8 target - never a hidden number). */
function eraResource(layer) {
	return player[layer].sparks;
}
/** The constant floor of an upgrade's multiplier (TUNING-driven). */
function multBase(eraIndex, idx) {
	return TUNING.upgBase + (idx % 6) * TUNING.upgStep + eraIndex * TUNING.upgEra;
}
function upgradeDesc(eraIndex, id, idx, kind) {
	var flat = ((multBase(eraIndex, idx) - 1) * 100).toFixed(2);
	var en = {
		K1: "Truth rate +" + flat + "%.",
		K2: "Truth rate +" + flat + "%, shaped by your Sparks.",
		K3: "Truth rate +" + flat + "%, also fed by your named resources.",
		K4: "The named mechanic of this era grows stronger.",
		K5: "Ladder costs in this era fall slightly.",
		K6: "Conditional: the bonus only applies past a threshold.",
		K7: "Unlocks the next stretch of the ladder.",
		K8: "Generates Proof Sparks every second.",
	}[kind];
	var zh = {
		K1: "真值速率 +" + flat + "%。",
		K2: "真值速率 +" + flat + "%，受火花塑形。",
		K3: "真值速率 +" + flat + "%，同时受具名资源滋养。",
		K4: "本时代的具名机制增强。",
		K5: "本时代阶梯花费略微降低。",
		K6: "条件生效：达到阈值后才提供加成。",
		K7: "解锁阶梯的下一段。",
		K8: "每秒生成证明火花。",
	}[kind];
	return t(en, zh);
}
function clickBank(layer, id) { return player[layer].banks[id] }
function setBank(layer, id, v) { player[layer].banks[id] = v.max(0) }
function clickGain(layer, id) {
	var g = player[layer].sparks.mul(0.05).mul(1 + id * 0.1);
	return g.max(new Decimal(1));
}
/**
 * Era-IV ascension rung: a DISCRETE jump. Truth itself gains `add` layers,
 * once. This is the only mechanism that can cross into tower territory
 * (design-brief D4: no smooth curve reaches layer 5 in bounded time).
 */
function claimTranscendence(layer, id, cost, add) {
	player[layer].points = player[layer].points.sub(cost)
	player[layer].spentOnBuyables = player[layer].spentOnBuyables.add(cost)
	player[layer].points = player[layer].points.layeradd(add, 10)
	player[layer].transcend = player[layer].transcend.add(add)
	player[layer].ascents = player[layer].ascents + 1;   // plain count
	player[layer].rungs[id] = true;
}
/** Era-II tick: the running proof converts banked clicks into Sparks. */
function advanceProofRun(layer, diff) {
	var gained = new Decimal(0);
	for (var i = 11; i <= 20; i++) gained = gained.add(player[layer].banks[i]);
	player[layer].sparks = player[layer].sparks.add(gained.mul(0.01).mul(diff));
}
/** Era-III board placement. */
function assembleSymbol(layer, id) {
	var d = getGridData(layer, id);
	setGridData(layer, id, d + 1);
}
/** Era-III board settle: a full row of placed symbols yields Charge. */
function resolveBoard(layer, diff) {
	var solved = 0;
	for (var r = 1; r <= 10; r++) {
		var full = true;
		for (var c = 1; c <= 10; c++) if (getGridData(layer, r * 100 + c) < 3) { full = false; break }
		if (full) solved++;
	}
	player[layer].charge = player[layer].charge.add(new Decimal(solved).mul(diff * 2));
	player[layer].boardsSolved = player[layer].boardsSolved + solved;
	if (solved > 0) for (var r2 = 1; r2 <= 10; r2++) for (var c2 = 1; c2 <= 10; c2++) {
		var id2 = r2 * 100 + c2;
		if (getGridData(layer, id2) >= 3) setGridData(layer, id2, 0);
	}
	return solved;
}

/** True while a trial's handicap is active. */
function isChallengeBlocked(layer, id) { return inChallenge(layer, id) }
/** Q6 buy-side automation: buy any affordable ladder rung. */
function autoBuyLadder(layer, ids) {
	for (const id of ids) {
		let b = tmp[layer].buyables[id];
		if (!b) continue;
		if (player[layer].points.lt(b.cost)) continue;
		buyBuyable(layer, id);
	}
}
/** Era-IV automation: buy an affordable ascension rung (once each). */
function autoBuyRungs(layer, ids) {
	for (const id of ids) {
		if (player[layer].rungs[id]) continue;
		let b = tmp[layer].buyables[id];
		if (!b) continue;
		if (player[layer].points.lt(b.cost)) continue;
		buyBuyable(layer, id);
	}
}
/** Q6 buy-side automation: buy any affordable, unlocked upgrade. */
function autoBuyUpgrades(layer) {
	for (let row = 1; row <= 60; row++) {
		for (let col = 1; col <= 5; col++) {
			const id = row * 10 + col;
			const u = layers[layer].upgrades[id];
			if (!u) continue;
			if (hasUpgrade(layer, id)) continue;
			if (!run(u.unlocked, u)) continue;
			if (!canAffordUpgrade(layer, id)) continue;
			buyUpgrade(layer, id);
		}
	}
}

