	// Production: ONE currency, so Truth is made here, not by getPointGen().
	// addPoints() is the only writer of best/total (03 §4.1 invariant 3).
	// RATE architecture (design-brief §11): rate = baseRate x mults, all O(1).
	update(diff) {
		if (!player.t.unlocked) return

		var rate = truthRate();   // mod.js: the single definition of the economy

		if (rate.gt(0)) addPoints("t", player.t.points.mul(rate).mul(diff));

		// --- secondary resources ----
		if (player.t.points.gte(eraGate(0))) {
			var sparkRate = this.sparkRate();   // every K8 upgrade
			if (hasMilestone("t", 3)) sparkRate = sparkRate.add(player.t.points.mul(TUNING.sparkMilestoneRate));
			// spark milestones multiply the whole rate (TUNING-driven)
			var MS = TUNING.expandMilestones();
			for (var mid in MS) {
				var g = MS[mid];
				if (g.type === "spark" && hasMilestone("t", +mid)) sparkRate = sparkRate.mul(g.v);
			}
			if (sparkRate.gt(0)) player.t.sparks = player.t.sparks.add(sparkRate.mul(diff));
		}
		if (eraIndex() >= 1 && !isChallengeBlocked("t", 12) && !isChallengeBlocked("t", 21) && !isChallengeBlocked("t", 32) && !isChallengeBlocked("t", 43))
			advanceProofRun("t", diff);
		if (eraIndex() >= 2 && !isChallengeBlocked("t", 23) && !isChallengeBlocked("t", 31) && !isChallengeBlocked("t", 34))
			resolveBoard("t", diff);

		// --- buy-side automation (Q6 classic, 6 steps) -------------------
		if (player.t.autoBuy0) autoBuyLadder("t", [11]);
		if (player.t.autoBuy1) autoBuyLadder("t", [11, 12]);
		if (player.t.autoBuy2) { autoBuyLadder("t", [11, 12, 13, 14]); autoBuyRungs("t", [21, 22, 23, 24]); }
		if (player.t.autoUpg0) autoBuyUpgrades("t");
		if (player.t.autoUpg1) autoBuyUpgrades("t");
		if (player.t.autoUpg2) autoBuyUpgrades("t");

		// track the best ever reached (drives every milestone + achievement)
		player.truthBest = player.truthBest.max(player.t.best);
		player.erasSeen = Math.max(player.erasSeen, eraIndex() + 1);
	},

	// ---- era III board. 'grid' singular (handbook 11 §6 ghost-field table),
	// ---- base-100 ids (hard rule 10), getStartData mandatory (rule T-GRID). ----
	grid: {
		rows: 10, cols: 10, maxRows: 10, maxCols: 10,
		getStartData() { return 0 },
		getUnlocked(id) { return eraIndex() >= 2 },
		getCanClick(data, id) {
			return !isChallengeBlocked("t", 23) && !isChallengeBlocked("t", 31) && !isChallengeBlocked("t", 34)
		},
		getTitle(data, id) { return t("Symbol ", "符号 ") + id },
		getDisplay(data, id) { return data + " / 3" },
		getStyle(data, id) {
			return data >= 3 ? {'background-color': '#8a5fbf'} : {'background-color': '#2a2438'}
		},
		onClick(data, id) { assembleSymbol(this.layer, id) },
		getTooltip() { return t("Place three of a symbol to complete a row.", "每行放满三个同符号即完成一行。") },
	},

