	// =====================================================================
	// Organization (handbook 10 §3): 5 content groups => microtabs are
	// MANDATORY, not optional (D-MICROTABS FAILs at >=16 content items).
	// =====================================================================
	tabFormat: [
		"main-display",
		["display-text", function() {
			return t("Era ", "当前时代：") + ["I · Axioms 公理", "II · Proofs 证明", "III · Transcendence 超越", "IV · Infinity 无穷"][eraIndex()] +
				" &nbsp;|&nbsp; " + t("Ascensions bought: ", "已飞升：") + player.t.ascents
		}],
		["display-text", function() {
			var span = player.t.points.slog(10).sub(new Decimal("1e-64").slog(10));
			return t("Span crossed: ", "已跨越跨度：") + format(span) + " / 8.02 slog &nbsp;&nbsp;" +
				t("F11 = ", "F11 = ") + format(TRUTH_F11);
		}],
		["display-text", function() {
			return t("Truth rate: ", "真值速率：") + format(truthRate().mul(100)) + "% / s";
		}],
		["microtabs", "truthTabs"],
	],

